using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using SlopProX;
class V8CoreTests {
 static List<string> log=new List<string>();static int failed;static string root;
 class Unavailable:Exception{public Unavailable(string reason):base(reason){}}
 static void Check(bool b,string reason){if(!b)throw new Exception(reason);}static void Test(string name,Action a){try{a();log.Add("PASS "+name);}catch(Unavailable ex){log.Add("NOT RUN "+name+" :: "+ex.Message);}catch(Exception ex){failed++;log.Add("FAIL "+name+" :: "+ex);}File.WriteAllLines(Path.Combine(root,"core.txt"),log);}
 static string Midi(){string file=Path.Combine(root,"score.mid");using(var w=new BinaryWriter(File.Create(file))){w.Write(Encoding.ASCII.GetBytes("MThd"));w.Write(new byte[]{0,0,0,6,0,0,0,1,1,224});byte[] data={0,255,81,3,7,161,32,0,255,88,4,4,2,24,8,0,144,60,100,0x83,0x60,128,60,0,0,255,47,0};w.Write(Encoding.ASCII.GetBytes("MTrk"));w.Write(new byte[]{0,0,0,(byte)data.Length});w.Write(data);}return file;}
 static float Peak(float[] a){return a.Select(Math.Abs).DefaultIfEmpty(0).Max();}
 static int Main(string[] args){root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("SLOPX_PROFILE",Path.Combine(root,"profile"));
 Test("PCM Sampler multisamples are cached, independently generated and pitch-transposed",()=>{var bank=SamplerBank.Load("Sub Bass");Check(Object.ReferenceEquals(bank,SamplerBank.Load("Sub Bass")),"Sample cache not reused");Check(bank.Length==8&&bank.All(s=>s.Pcm.Length>20000),"PCM multisamples missing");var sampler=new SamplerInstrument();sampler.Prepare("Sub Bass");var data=new float[48000*2];sampler.Render(data,48000,48000,"Sub Bass",new[]{new MidiEventPacket(0,0x90,69,100)},1);int crossings=0;for(int i=5001;i<45000;i++)if(data[(i-1)*2]<0&&data[i*2]>=0)crossings++;double frequency=crossings*48000.0/39999;Check(frequency>436&&frequency<444,"Sampler pitch incorrect: "+frequency);log.Add("SAMPLER A4 measured Hz="+frequency+" peak="+Peak(data));});
 Test("Selected unarmed MIDI instrument produces PCM while transport is stopped",()=>{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("MIDI thru",TrackType.Midi);Check(!t.Armed,"Fixture should be unarmed");p.Tracks.Add(t);using(var engine=new ArrangementEngine(new AppSettings())){engine.SetProject(p);engine.SetMidiThruTrack(t.Id);engine.InjectMidi(0x90,60,100);var data=new float[512*2];engine.Render(data,512,0);Check(Peak(data)>.005,"Unarmed selected MIDI thru was silent");engine.InjectMidi(0x80,60,0);for(int i=0;i<120;i++)engine.Render(data,512,0);Check(Peak(data)<.0001,"Note-off left stuck voices");Check(engine.MidiMessageCount==2,"MIDI messages not counted");}});
 Test("Unselected unarmed instrument stays silent; input routes only to the selected instrument",()=>{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("Selected",TrackType.Midi);var other=ProjectFactory.CreateTrack("Not selected",TrackType.Midi);p.Tracks.Add(t);p.Tracks.Add(other);using(var engine=new ArrangementEngine(new AppSettings())){engine.SetProject(p);engine.SetMidiThruTrack(t.Id);engine.InjectMidi(0x90,60,100);engine.Render(new float[1024],512,0);Check(engine.TrackPeak(t.Id)>.005&&engine.TrackPeak(other.Id)<.0001,"MIDI thru routing mismatch");}});
 Test("WinMM opens actual configured Keystation input endpoint without modifying other applications",()=>{var port=WinMmDevices.MidiInputs().FirstOrDefault(d=>d.Name=="Keystation 49");if(port==null)throw new Unavailable("Keystation endpoint unavailable");using(var input=new MidiInputDevice(port.Id)){Thread.Sleep(150);log.Add("OPENED MIDI "+port.Name+" id="+port.Id+"; physical note performance NOT RUN");}});
 Test("Standard MIDI file imports through unified project exchange and preserves tempo, meter and notes",()=>{string file=Midi();var result=ProjectExchange.Import(file,Path.Combine(root,"midi-media"));Check(result.Project.Tracks.Sum(t=>t.Regions.Sum(r=>r.Notes.Count))==1,"SMF note missing");Check(Math.Abs(result.Project.Tempo-120)<.01&&result.Project.TimeSignatureNumerator==4,"SMF tempo/meter lost");Check(result.Project.Tracks.All(t=>!t.ExternalMidi),"SMF defaults to silent external output");});
 Test("FLP factory demo subset is readable and imported notes receive explicit Sampler audition",()=>{string folder=@"C:\Program Files\Image-Line\FL Studio 2024\Data\Demo projects";if(!Directory.Exists(folder))throw new Unavailable("FL Studio factory demos unavailable");var files=Directory.GetFiles(folder,"*.flp",SearchOption.AllDirectories).OrderBy(f=>new FileInfo(f).Length).Where(f=>new FileInfo(f).Length>5000).Take(8).ToList();Check(files.Count==8,"8 installed factory fixtures unavailable");foreach(string file in files){var result=ProjectExchange.Import(file,Path.Combine(root,"fl-media"));int notes=result.Project.Tracks.Sum(t=>t.Regions.Sum(r=>r.Notes.Count));Check(notes>0,"No notes imported from "+Path.GetFileName(file));Check(result.Project.Tracks.Where(t=>t.Type==TrackType.Midi).All(t=>!t.ExternalMidi),"FLP MIDI left unassigned");Check(result.Warnings.Any(w=>w.Contains("NOT restored")),"Missing timbre conversion disclosure");log.Add("FLP "+Path.GetFileName(file)+" tracks="+result.Project.Tracks.Count+" regions="+result.Project.Tracks.Sum(t=>t.Regions.Count)+" notes="+notes);}});
 Test("MIDI comp slices drive actual note playback, including a trimmed held note",()=>{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("MIDI takes",TrackType.Midi);var a=ProjectFactory.CreateRegion("Take A",0,4);a.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=4,Pitch=60,Velocity=100});var b=ProjectFactory.CreateRegion("Take B",0,4);b.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=4,Pitch=67,Velocity=90});t.Regions.Add(a);t.Regions.Add(b);p.Tracks.Add(t);p.Studio.Comps.Add(new CompLane{TrackId=t.Id,Takes=new List<Guid>{a.Id,b.Id},Slices=new List<CompSlice>{new CompSlice{RegionId=b.Id,StartBeat=1,EndBeat=3}}});using(var engine=new ArrangementEngine(new AppSettings())){var silence=engine.RenderOffline(p,4096,0);var active=engine.RenderOffline(p,4096,1);Check(Peak(silence)<.00001,"Unused take leaked into comp");Check(Peak(active)>.005,"MIDI comp slice is silent");}});
 Test("Chord progressions validate, preserve native state and generate major/minor/seventh/suspended MIDI",()=>{Check(ChordProgression.Pitches("Bbmaj7").SequenceEqual(new[]{70,74,77,81}),"Bbmaj7 wrong");Check(ChordProgression.Pitches("Dm").SequenceEqual(new[]{62,65,69}),"Dm wrong");bool invalid=false;try{ChordProgression.Pitches("Q#");}catch(ArgumentException){invalid=true;}Check(invalid,"Invalid chord accepted");var p=new ProjectDocument();p.Studio.Chords=ChordProgression.Parse("Am | Fmaj7 | C | G",4);p.Tracks.Add(ChordProgression.CreateTrack(p.Studio.Chords));string file=Path.Combine(root,"chords.slopdaw");ProjectFile.SaveAtomic(p,file);Check(ProjectFile.Load(file).Studio.Chords.Count==4,"Chord state lost");});
 Test("Original Melodic House sample saves/reopens with chords, launcher and effects; rendered PCM is finite",()=>{var p=DemoProjects.MelodicHouse();string file=Path.Combine(root,"EDM Sample - Melodic House.slopdaw");Directory.CreateDirectory(Path.GetDirectoryName(file));ProjectFile.SaveAtomic(p,file);var loaded=ProjectFile.Load(file);Check(ProjectFile.Equivalent(p,loaded),"Demo round trip mismatch");Check(loaded.Tracks.Count==14&&loaded.Studio.Chords.Count==80,"Demo content incomplete");using(var engine=new ArrangementEngine(new AppSettings())){float[] audio=engine.RenderOffline(loaded,48000*4,96);Check(Peak(audio)>.015&&audio.All(v=>!Single.IsNaN(v)&&!Single.IsInfinity(v)),"Demo PCM silent or invalid");string preview=Path.Combine(root,"Melodic-House-preview.wav");using(var wave=new ExportWaveWriter(preview,48000,2,24,false))wave.Write(audio,0,audio.Length);log.Add("DEMO peak="+Peak(audio)+" notes="+loaded.Tracks.Sum(t=>t.Regions.Sum(r=>r.Notes.Count)));}});
 Test("Sampler/mixer callback benchmark on Melodic House arrangement",()=>{var p=DemoProjects.MelodicHouse();using(var engine=new ArrangementEngine(new AppSettings{SampleRate=48000,BufferFrames=512})){engine.PrepareOffline(p,96);var data=new float[1024];for(int i=0;i<32;i++)engine.Render(data,512,0);var ms=new List<double>();for(int i=0;i<512;i++){long begin=Stopwatch.GetTimestamp();engine.Render(data,512,0);ms.Add((Stopwatch.GetTimestamp()-begin)*1000.0/Stopwatch.Frequency);}ms.Sort();double p95=ms[(int)(ms.Count*.95)],p99=ms[(int)(ms.Count*.99)],max=ms.Last();log.Add("BENCHMARK rate=48000 frames=512 periodMs=10.667 blocks=512 p95Ms="+p95.ToString("0.000")+" p99Ms="+p99.ToString("0.000")+" maxMs="+max.ToString("0.000"));Check(p95<10.667,"95th percentile exceeds the buffer period");}});
 Test("MIT complete text and legal clauses are present in runtime resources",()=>{string license=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"LICENSE"));Check(license.Contains("Permission is hereby granted, free of charge")&&license.Contains("THE SOFTWARE IS PROVIDED")&&license.Contains("IN NO EVENT"),"MIT legal text incomplete");});
 Test("Shortcut registry keeps unique supported bindings and includes all tested editing contexts",()=>{ShortcutRegistry.ValidateUniqueActiveAssignments();foreach(var command in new[]{AppCommand.SelectAll,AppCommand.Copy,AppCommand.Cut,AppCommand.Paste,AppCommand.ZoomVerticalOut,AppCommand.ZoomVerticalIn,AppCommand.InvertSelection})Check(ShortcutRegistry.Find(command)!=null,"Shortcut unavailable: "+command);log.Add("REGISTRY active="+ShortcutRegistry.Bindings.Count(b=>b.Implemented)+" total="+ShortcutRegistry.Bindings.Count);});
 if(args.Length>1)Test("FFmpeg compressed audio and extensible PCM/float WAV imports use a validated canonical sample format",()=>{string movie=Path.Combine(args[1],"fixture.mp4");string wave=MediaImport.Decode(movie,Path.Combine(root,"decode"));var info=WaveAudio.Inspect(wave);Check(info.EncodingTag==1&&info.BitsPerSample==24&&info.DataBytes>1000,"FFmpeg 24-bit extensible WAV rejected or changed");var floating=WaveAudio.Inspect(Path.Combine(args[1],"fixture-float.wav"));Check(floating.EncodingTag==3&&floating.BitsPerSample==32,"Extensible IEEE float WAV not normalized");var pcm=WaveAudio.Load(wave);Check(pcm.Samples.Length==info.DataBytes,"Extensible PCM byte count mismatch");byte[] bytes=File.ReadAllBytes(wave);int fmt=Encoding.ASCII.GetString(bytes,0,Math.Min(bytes.Length,300)).IndexOf("fmt ",StringComparison.Ordinal);Check(fmt>=0&&BitConverter.ToUInt16(bytes,fmt+8)==65534,"Fixture is not real extensible WAV");bytes[fmt+8+24]=0x55;string invalid=Path.Combine(root,"unsupported-subformat.wav");File.WriteAllBytes(invalid,bytes);bool rejected=false;try{WaveAudio.Inspect(invalid);}catch(InvalidDataException){rejected=true;}Check(rejected,"Unsupported WAV subtype accepted");});
 if(args.Length>1)Test("MP4 and MOV real FFmpeg frame decoding and movie reference persistence",()=>{foreach(string extension in new[]{"mp4","mov"}){string file=Path.Combine(args[1],"fixture."+extension);using(var image=VideoDecoder.Frame(file,.5)){Check(image.Width>100&&image.Height>100,"Decoded frame dimensions invalid");image.Save(Path.Combine(root,"movie-"+extension+".png"));}var p=new ProjectDocument();p.Studio.Video=new VideoReference{Path=file,StartBeat=4};string project=Path.Combine(root,"movie-"+extension+".slopdaw");ProjectFile.SaveAtomic(p,project);Check(ProjectFile.Load(project).Studio.Video.Path==file,"Movie reference lost");}});
 log.Add("NOT RUN physical MIDI key performance and vendor-specific FL instrument restoration.");File.WriteAllLines(Path.Combine(root,"core.txt"),log);Console.WriteLine(String.Join(Environment.NewLine,log.ToArray()));return failed==0?0:1;
 }
}
